import{_ as t,a,o,a6 as i}from"./chunks/framework.CJDy2q7X.js";const h=JSON.parse('{"title":"Categories","description":"","frontmatter":{"outline":false,"apiType":"rest"},"headers":[],"relativePath":"api/rest-api/admin/catalog/categories/index.md","filePath":"api/rest-api/admin/catalog/categories/index.md","lastUpdated":1787725411000}'),r={name:"api/rest-api/admin/catalog/categories/index.md"};function d(s,e,c,n,l,g){return o(),a("div",null,e[0]||(e[0]=[i('<h1 id="categories" tabindex="-1">Categories <a class="header-anchor" href="#categories" aria-label="Permalink to &quot;Categories&quot;">​</a></h1><p>Categories are the storefront&#39;s browsing tree — the sections customers navigate and products are assigned to. The Categories menu lists them (flat or as a nested tree), shows a single category, and creates / edits / deletes / moves them. It mirrors the admin <strong>Catalog → Categories</strong> screen.</p><h2 id="flat-list-vs-tree" tabindex="-1">Flat list vs. tree <a class="header-anchor" href="#flat-list-vs-tree" aria-label="Permalink to &quot;Flat list vs. tree&quot;">​</a></h2><p>Two read shapes for the same data:</p><ul><li><strong>List</strong> (<code>GET /api/admin/catalog/categories</code>) — a flat, paginated, filterable datagrid of categories. Each row carries the category&#39;s own fields plus its <code>parentId</code>.</li><li><strong>Tree</strong> (<code>GET /api/admin/catalog/categories/tree</code>) — the full nested hierarchy, each node carrying its <code>children</code> recursively. Use this to render the category tree in one call.</li></ul><h2 id="hierarchy-status-display" tabindex="-1">Hierarchy, status, display <a class="header-anchor" href="#hierarchy-status-display" aria-label="Permalink to &quot;Hierarchy, status, display&quot;">​</a></h2><ul><li><strong><code>parentId</code></strong> places a category under its parent. The root category (<code>id = 1</code>) and any channel&#39;s root category are structural and <strong>cannot be deleted</strong>.</li><li><strong>Moving</strong> a category is just an update with a new <code>parentId</code> (and <code>position</code>) — there is no separate &quot;move&quot; endpoint.</li><li><strong><code>status</code></strong> (1 enabled / 0 disabled) and <strong><code>position</code></strong> (sort order among siblings).</li><li><strong><code>displayMode</code></strong> — what the category page shows: <code>products_and_description</code>, <code>products_only</code>, or <code>description_only</code>.</li><li><strong><code>translations</code></strong> hold the per-locale <code>slug</code>, <code>name</code>, <code>description</code>, and meta fields. <strong><code>filterableAttributeIds</code></strong> are the attributes used for this category&#39;s layered-navigation filters.</li></ul><p>The single-category endpoint embeds the full <code>translations</code> and <code>filterableAttributeIds</code> inline; the listing leaves those two out (they&#39;re detail-only).</p><h2 id="endpoints-in-this-menu" tabindex="-1">Endpoints in this menu <a class="header-anchor" href="#endpoints-in-this-menu" aria-label="Permalink to &quot;Endpoints in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Endpoint</th></tr></thead><tbody><tr><td><a href="/api/rest-api/admin/catalog/categories/categories-listing.html">List categories</a></td><td><code>GET /api/admin/catalog/categories</code></td></tr><tr><td><a href="/api/rest-api/admin/catalog/categories/categories-tree.html">Category tree</a></td><td><code>GET /api/admin/catalog/categories/tree</code></td></tr><tr><td><a href="/api/rest-api/admin/catalog/categories/categories-detail.html">Category detail</a></td><td><code>GET /api/admin/catalog/categories/{id}</code></td></tr><tr><td><a href="/api/rest-api/admin/catalog/categories/categories-create.html">Create category</a></td><td><code>POST /api/admin/catalog/categories</code></td></tr><tr><td><a href="/api/rest-api/admin/catalog/categories/categories-update.html">Update / move category</a></td><td><code>PUT /api/admin/catalog/categories/{id}</code></td></tr><tr><td><a href="/api/rest-api/admin/catalog/categories/categories-delete.html">Delete category</a></td><td><code>DELETE /api/admin/catalog/categories/{id}</code></td></tr><tr><td><a href="/api/rest-api/admin/catalog/categories/categories-mass-delete.html">Mass delete</a></td><td><code>POST /api/admin/catalog/categories/mass-delete</code></td></tr><tr><td><a href="/api/rest-api/admin/catalog/categories/categories-mass-update-status.html">Mass update status</a></td><td><code>POST /api/admin/catalog/categories/mass-update-status</code></td></tr></tbody></table><p>Reads require <code>catalog.categories.view</code>; writes require the matching <code>catalog.categories.create</code> / <code>.edit</code> / <code>.delete</code> permission.</p>',11)]))}const m=t(r,[["render",d]]);export{h as __pageData,m as default};
